    #   [{"legs": ("S", "W", "W", "E"), "via": ["-794701342#0", "794701342#0"]},   # via: 재진입 전에 들를 엣지
    #    ("N", "S"), ("NE", "SW"), ("E", "W"), ("S", "N"), ("SW", "N"), ("W", "E")]
    #   via 엣지 id는 학습 지도(OSM 모드) 기준이다. 경로 길이가 3 km까지라 SIMULATION["max_steps"]는 3000 이상.
    # 시연(영상)용 경로. test.py --demo-route 로 주행할 때만 쓴다 (OSM 도로망 전용).
