# ──────────────────────────────────────────────────────────────
# 3) 배경 교통류 (SUMO가 알아서 운전하는 일반 차량들)
#    각 도로의 inflow를 나머지 도로로 나눠 보낸다 (도착 도로의 진출 차로 수
#    비율로 배분, ROAD["osm"]["banned_turns"] 방향은 제외). 우회전 차량은
#    우회전 연결로를 이용한다.
# ──────────────────────────────────────────────────────────────
TRAFFIC = {
    "max_speed": 16.0,        # 배경차 공통 기본 최고속도 (m/s).
                              # 실제 속도는 제한속도 × 개체별 속도 편차로 정해진다.
    "depart_speed": "max",    # 신규 차량 진입 속도 ("max" = 안전한 최고속도)

    # ──────────────────────────────────────────────────────
    # 배경차 컨트롤러(차량추종모델) 믹스
    #
    # 실제 도로에는 운전 스타일이 제각각인 차들이 섞여 있다. 배경차를
    # 단일 모델로만 채우면 에이전트가 그 모델의 버릇에 과적합되므로,
    # 서로 다른 SUMO carFollowModel 4종을 확률적으로 섞어 투입한다.
    # (SUMO의 vTypeDistribution 기능 사용 — road_builder.py가 생성)
    #
    # probability: 투입 비율 (합이 1이 아니어도 자동 정규화됨)
    # max_speed  : 컨트롤러별 희망속도 상한 (생략 시 위 공통값)
    # speed_dev  : 같은 타입 안에서도 개체별 희망속도 편차 (0~1)
    # color      : GUI에서 구분용 (ego의 빨강은 피할 것)
    # sigma      : Krauss 계열 전용 "운전자 불완전성" (다른 모델은 무시)
    # ──────────────────────────────────────────────────────
    "controllers": {
        "krauss": {   # 산만한 인간 운전자
            "probability": 0.35,
            "carFollowModel": "Krauss",
            "accel": 2.0, "decel": 4.5,
            "tau": 1.0, "min_gap": 2.5,
            "sigma": 0.3,
            "max_speed": 14.0, "speed_dev": 0.15,
            "color": "1,1,0",    # 노랑
        },
        "idm": {      # 부드러운 표준 인간 모델
            "probability": 0.30,
            "carFollowModel": "IDM",
            "accel": 1.8, "decel": 3.5,
            "tau": 1.2, "min_gap": 2.0,
            "max_speed": 16.0, "speed_dev": 0.10,
            "color": "0,1,1",    # 시안
        },
        "eidm": {     # 반응지연 있는 현실적 인간
            "probability": 0.20,
            "carFollowModel": "EIDM",
            "accel": 2.0, "decel": 4.0,
            "tau": 1.1, "min_gap": 2.0,
            "max_speed": 16.5, "speed_dev": 0.10,
            "color": "1,0.6,0",  # 주황
        },
        "acc": {      # 크루즈 차량
            "probability": 0.15,
            "carFollowModel": "ACC",
            "accel": 2.0, "decel": 4.0,
            "tau": 1.5, "min_gap": 2.0,
            "max_speed": 19.0, "speed_dev": 0.05,
            "color": "1,0,1",    # 마젠타
        },
    },

    # ──────────────────────────────────────────────────────
    # 프리필(pre-fill): 에피소드 시작 시 배경차를 각 진입 도로에 미리 배치
    #
    # flow는 도로 끝(입구)에서만 차를 만들기 때문에, 그냥 시작하면
    # 교차로 주변이 한동안 비어 있다. 프리필은 reset()마다 각 진입 도로에
    # 차량을 일정 간격(± 무작위 흔들림)으로 미리 심어서 첫 스텝부터
    # 교통류 속에서 학습이 이뤄지게 한다. 경로는 그 도로의 flow 비율대로 고른다.
    # ──────────────────────────────────────────────────────
    "prefill": {
        "enabled": True,
        "start_offset": 40,    # ego 출발 도로의 시작 이 구간은 비워둠 (ego 진입 공간)
        "end_margin": 15,      # 진입 도로 끝(분기 지점 앞) 이 구간도 비워둠
        "spacing": None,       # 차선당 배치 간격(m). None이면 도로별 교통량에서
                               # 자동 계산: 제한속도 / (차선당 유량)
        "spacing_jitter": 0.45,  # 간격의 ±45% 무작위 흔들림
    },

    # ──────────────────────────────────────────────────────
    # 연산교차로 실측 교통량 기반 수요 (OD별 flow)
    #
    # 출처: 부산광역시 「2025년 교통조사 분석용역 결과서」 차량교통량 부록
    #       (조사지점 1. 연산교차로, 방향별 × 24시간 × 차종별, 단위: 대/시)
    #       자세한 내용은 env/demand/README.md 참고.
    #
    # osm_builder.build_osm()이 연산교차로 OSM 도로망의 배경 교통을 이 OD로
    # 만든다 (ROAD["legs"]의 inflow 가정값 대신). 방면 → leg 매핑("legs")을
    # 전부 None으로 두면 꺼지고, 예전처럼 inflow 가정값으로 만든다.
    # 실측에 없는 5개 방향은 ROAD["osm"]["banned_turns"]의 좌회전 금지와 같다.
    # 신호 녹색 시간은 시나리오에 맞춰 SIGNAL["green_by_scenario"]에서 고른다.
    # ──────────────────────────────────────────────────────
    "demand": {
        "csv": "demand/yeonsan_2025_od_hourly_by_class.csv",  # env/ 기준 경로
        "scenario": "normal",       # 아래 scenarios 중 하나
        "scenarios": {              # hour: CSV의 시간대(시작 시각, "00"~"23")
            "light":  {"hour": "05"},   # 한산  — 1,902대/시 (이륜차 포함 총량)
            "normal": {"hour": "12"},   # 보통  — 5,015대/시
            "heavy":  {"hour": "18"},   # 혼잡  — 5,567대/시 (오후 첨두)
        },
        "scale": 0.7,               # 실측 대비 배율 (1.0 = 실측 그대로).
                                    # ※ 2026-11-19 0.5 → 0.7 (곧은 진입로 지도, 동시 녹색 신호):
                                    #   배경 교통 1,800초 — 0.5: 1,496대 투입·대기 0·순간이동 4,
                                    #   0.7: 약 2,030대 투입·입구 대기 약 4%·순간이동 10~12,
                                    #   1.0: 2,529대 투입·입구 대기 17%·순간이동 21.
                                    #   최종 모델(models/yeonsan_7routes_final)은 0.7에서 완주 96.7%·충돌 1.4%,
                                    #   1.0에서는 87%·5% (README). 아래는 0.5로 정했을 때의 기록:
                                    # ※ 임시값 0.5: SUMO에서 연산교차로 통과량이 시간당 약
                                    #   2,200대에서 막힌다 (python docs/research/check_demand.py).
                                    #   2026-11-18 확인: 동시 녹색 7현시로 바꿔도 같음 — 병목은
                                    #   연산교차로 신호가 아니라 상류(중앙대로·반송로 일반 2차로 +
                                    #   1 km 안에 줄지은 가정 신호, 정지선 앞 넓은 구간이 짧음).
                                    #   배율 0.75·1.0에서는 통과량이 오히려 줄고 순간이동·투입 대기가
                                    #   급증. 실측(4,303대/h)으로 올리려면 상류 신호의 실제 시간(연동)이
                                    #   필요하다.
        "include_motorcycle": False,  # 이륜차(전체의 7.7%)를 수요에 넣을지.
                                      # 배경차가 전부 승용차 모델이라 기본은 제외
        "include_bus": False,       # 버스(12시 204대/시)를 승용차 모델로 넣을지.
                                    # 신호 녹색 시간을 버스 제외 교통량으로 계산했고,
                                    # 중앙대로 버스 상당수는 BRT 차로로 다녀서 기본은 제외
        "poisson": True,            # True: 포아송 도착 (period="exp(λ)"),
                                    # False: 등간격 (vehsPerHour)
        # 방면 이름(CSV의 from/to) → ROAD["legs"]의 id
        "legs": {
            "부산시청":   "SW",   # 중앙대로 서면 방면
            "부산교대":   "N",    # 중앙대로 동래 방면
            "안락교차로": "NE",   # 반송로
            "연산터널":   "E",    # 고분로
            "신리삼거리": "S",    # 월드컵대로 남쪽
            "종합운동장": "W",    # 월드컵대로 사직 방면
        },
    },
}
